from pathlib import Path
import subprocess,json,gzip,datetime,hashlib,sys
p=Path(__file__).resolve().parent;r=p.parents[2]
def sha(f):return hashlib.sha256(f.read_bytes()).hexdigest()
cases={'missing': '#let f=[].func()\n#f()', 'empty': '#let f=[].func()\n#let c=f(())\n#repr((c.func(),c.fields()))', 'single': '#let f=[].func()\n#let c=f(([A],))\n#repr((c.func(),c.fields()))', 'many': '#let f=[].func()\n#let c=f(([A],[B]))\n#repr((c.func(),c.fields()))', 'nested': '#let f=[].func()\n#repr(f((([A]+[B]),[C])).children)', 'named': '#let f=[].func()\n#repr(f(children:([A],[B])).fields())', 'wrong-str': '#let f=[].func()\n#f("A")', 'wrong-content': '#let f=[].func()\n#f([A])', 'wrong-int': '#let f=[].func()\n#f((1,))', 'array-str': '#let f=[].func()\n#repr(f(("A","B")).fields())', 'array-none': '#let f=[].func()\n#f((none,))', 'extra': '#let f=[].func()\n#f((),())', 'extra-named': '#let f=[].func()\n#f((),x:1)', 'named-and-pos': '#let f=[].func()\n#f((),children:([A],))', 'unknown-only': '#let f=[].func()\n#f(x:1)', 'body': '#let f=[].func()\n#f[A]', 'alias': '#let f=([A]+[B]).func()\n#let g=f\n#repr(g(([C],)).children)', 'with': '#let f=[].func().with(([A],))\n#repr(f().fields())', 'selector': '#repr(selector([].func()))', 'where': '#repr([].func().where(children:([A],[B])))', 'where-wrong-value': '#repr([].func().where(children:12))', 'where-unknown': '#repr([].func().where(missing:1))', 'selector-partial': '#repr(selector([].func().with(())))', 'where-partial': '#repr([].func().with(()).where())', 'counter': '#repr(counter([].func()))', 'counter-where': '#repr(counter([].func().where()))', 'query': '#context repr(query([].func()))', 'query-where': '#context repr(query([].func().where(children:())))', 'show': '#let f=[].func()\n#show f:it=>[Y]\n#([A]+[B])', 'show-filter': '#let f=[].func()\n#show f.where(children:([A],[B])):it=>[Y]\n#([A]+[B])', 'set-empty': '#let f=[].func()\n#set f()\nA', 'set-children': '#let f=[].func()\n#set f(children:())\nA', 'func-eq': '#repr([].func()==([A]+[B]).func())', 'children-method': '#repr([].children())', 'children-method-effects': '#[].children(panic("BAD"))', 'array-symbol': '#let f=[].func()\n#repr(f((sym.alpha,none,"")).fields())', 'named-type': '#let f=[].func()\n#f(children:12)', 'bad-child-before-extra': '#let f=[].func()\n#f((1,),x:2)', 'bad-array-before-extra': '#let f=[].func()\n#f(12,x:2)', 'order-extra': '#let f=[].func()\n#f(x:1,(),())', 'set-pos': '#let f=[].func()\n#set f(())\nA', 'set-unknown': '#let f=[].func()\n#set f(x:1)\nA', 'set-effect': '#let f=[].func()\n#set f(children:panic("BAD"))\nA', 'set-partial': '#let f=[].func().with(())\n#set f()\nA', 'set-false': '#let f=[].func()\n#set f(children:panic("BAD")) if false\nA', 'show-empty': '#let f=[].func()\n#show f:it=>[Y]\n#[]', 'show-single': '#let f=[].func()\n#show f:it=>[Y]\n#f(([A],))', 'show-miss': '#let f=[].func()\n#show f.where(children:([C],)):it=>[Y]\n#([A]+[B])', 'show-styled': '#let f=[].func()\n#show f:it=>[Y]\n#text(fill:red)[A B]', 'show-once': '#let f=[].func()\n#let n=0\n#show f:it=>{ n+=1; [Y] }\n#([A]+[B])'}
rows=[]
meta={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'head':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'diffstat':subprocess.check_output(['git','diff','HEAD','--stat'],text=True),'status':subprocess.check_output(['git','status','--porcelain=v1','--untracked-files=all'],text=True),'binaries':{},'pin':'bd5ebec285505889e8ff1d4f68804ab147a699f3'}
for label,src in cases.items():
 f=p/('outputs/'+label+'.typ');f.write_text(src+'\n');row={'label':label,'source':src,'source_sha256':sha(f),'results':{}}
 for name,b in [('tekt',r/'target/debug/typst'),('vanilla',r/'lab/typst-original/target/release/typst')]:
  meta['binaries'][name]={'path':str(b),'sha256':sha(b)}
  out=p/('outputs/'+label+'-'+name+'.pdf');cmd=[str(b),'compile',str(f),str(out)];z=subprocess.run(cmd,text=True,capture_output=True,timeout=30);txt=subprocess.run(['pdftotext',str(out),'-'],capture_output=True,text=True).stdout if not z.returncode else '';row['results'][name]={'argv':cmd,'exit':z.returncode,'stderr':z.stderr,'text':' '.join(txt.split())}
 rows.append(row);print(label,[(k,v['exit'],v['text'] if not v['exit'] else v['stderr'].splitlines()[0]) for k,v in row['results'].items()],flush=True)
meta['cases']=rows
(p/(sys.argv[1]+'.json.gz')).write_bytes(gzip.compress(json.dumps(meta,indent=2).encode()))
